'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const crypto = require('node:crypto');
const { spawn } = require('node:child_process');
const [project, archivePath, npmCommand, packagePath] = process.argv.slice(2);

async function main() {
  assert.equal(process.versions.node, '26.13.0');
  assert.equal(fs.existsSync(project), false, 'Use a fresh project and cache');
  fs.mkdirSync(project, { recursive: true });
  fs.writeFileSync(path.join(project, 'package.json'), JSON.stringify({
    name: 'registry-consumer-project', version: '1.0.0', private: true,
  }) + '\n');
  const pkg = JSON.parse(fs.readFileSync(packagePath, 'utf8'));
  const archive = fs.readFileSync(archivePath);
  const integrity = 'sha512-' + crypto.createHash('sha512').update(archive).digest('base64');
  const archiveRoute = `/${pkg.name}/-/${pkg.name}-${pkg.version}.tgz`;
  const counts = { metadata: 0, tarball: 0 };
  const sockets = new Set();
  let registry;
  const server = http.createServer((request, response) => {
    assert.equal(request.method, 'GET');
    const route = request.url.split('?')[0];
    let bytes;
    if (route === '/' + pkg.name) {
      counts.metadata++;
      bytes = Buffer.from(JSON.stringify({
        name: pkg.name, 'dist-tags': { latest: pkg.version },
        versions: { [pkg.version]: { ...pkg, dist: {
          tarball: registry + archiveRoute, integrity,
          shasum: crypto.createHash('sha1').update(archive).digest('hex'),
        } } },
      }));
      response.setHeader('content-type', 'application/json');
    } else if (route === archiveRoute) {
      counts.tarball++;
      bytes = archive;
      response.setHeader('content-type', 'application/octet-stream');
    } else {
      response.writeHead(404);
      response.end('Unexpected fixture request');
      return;
    }
    response.setHeader('content-length', bytes.length);
    response.end(bytes);
  });
  server.on('connection', socket => {
    sockets.add(socket);
    socket.once('close', () => sockets.delete(socket));
  });
  try {
    await new Promise((resolve, reject) => {
      server.once('error', reject);
      server.listen(0, '127.0.0.1', resolve);
    });
    const address = server.address();
    assert.equal(address.address, '127.0.0.1');
    assert.ok(address.port > 0);
    registry = `http://127.0.0.1:${address.port}`;
    const result = await new Promise((resolve, reject) => {
      const child = spawn(npmCommand, ['install', '--registry=' + registry,
        '--no-audit', '--no-fund', '--foreground-scripts', pkg.name], {
        cwd: project, env: { ...process.env,
          npm_config_cache: path.join(project, '.npm-cache'),
          npm_config_update_notifier: 'false' },
        stdio: ['ignore', 'pipe', 'pipe'],
      });
      let stdout = '', stderr = '';
      child.stdout.setEncoding('utf8').on('data', data => { stdout += data; });
      child.stderr.setEncoding('utf8').on('data', data => { stderr += data; });
      child.once('error', reject);
      child.once('close', (code, signal) => resolve({ code, signal, stdout, stderr }));
    });
    process.stdout.write(result.stdout);
    process.stderr.write(result.stderr);
    assert.equal(result.code, 0);
    assert.equal(result.signal, null);
    assert.ok(counts.metadata > 0, 'npm must request registry metadata');
    assert.ok(counts.tarball > 0, 'npm must download the actual tarball');
    const installed = path.join(project, 'node_modules', pkg.name);
    assert.equal(require(installed).answer, 42);
    assert.equal(fs.readFileSync(path.join(installed, 'installed.marker'), 'utf8'),
      'real-npm-lifecycle\n');
    const lock = JSON.parse(fs.readFileSync(path.join(project, 'package-lock.json'), 'utf8'));
    const entry = lock.packages['node_modules/' + pkg.name];
    assert.equal(entry.resolved, registry + archiveRoute);
    assert.equal(entry.integrity, integrity);
    fs.writeFileSync(path.join(project, 'registry-observation.json'),
      JSON.stringify({ registry, counts, integrity }) + '\n');
  } finally {
    if (server.listening) await new Promise((resolve, reject) => {
      server.close(error => error ? reject(error) : resolve());
    });
  }
  assert.equal(server.listening, false);
  assert.equal(sockets.size, 0, 'Server connections must close normally');
  console.log('Controlled registry installation verified');
}
main().catch(error => { console.error(error); process.exitCode = 1; });

